def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('+', '-'):
                advance()
                rhs = parse_term()
                if tok[0] == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('*', '/'):
                advance()
                rhs = parse_factor()
                if tok[0] == '*':
                    val = val * rhs
                else:
                    # integer division truncating toward zero
                    sign = 1
                    a, b = val, rhs
                    if (a < 0) != (b < 0):
                        sign = -1
                    q = abs(a) // abs(b)
                    val = sign * q
            else:
                break
        return val

    def parse_factor():
        neg = False
        while True:
            tok = peek()
            if tok is not None and tok[0] == '-':
                advance()
                neg = not neg
            else:
                break
        val = parse_primary()
        if neg:
            val = -val
        return val

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'num':
            advance()
            return tok[1]
        elif tok[0] == '(':
            advance()
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        else:
            raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    return result

